SOURCE tests/procedures/support/fixture.sql;
CALL bank_lab.sp_expect_ok(DATABASE(),'transfer ordered forward','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)');
SET @p3_ok=(SELECT COUNT(*)=2 AND SUM(status='Completed')=2 AND SUM(transaction_type='TransferOut')=1 AND SUM(transaction_type='TransferIn')=1 FROM Transactions WHERE transfer_group_id=@p3_group);
CALL bank_lab.sp_assert_true(DATABASE(),'transfer paired legs',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_ok(DATABASE(),'transfer ordered reverse','CALL {db}.sp_transfer_funds(@p3_b,@p3_a,1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)');
