SET @p3_failed=(SELECT COUNT(*) FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_expect_error(DATABASE(),'transfer threshold boundary','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,100000,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5006);
SET @p3_ok=(SELECT COUNT(*)=@p3_failed+1 FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_assert_true(DATABASE(),'transfer threshold one Failed',@p3_ok,'Expected procedure contract');
SET @p3_failed=(SELECT COUNT(*) FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_expect_error(DATABASE(),'transfer same account','CALL {db}.sp_transfer_funds(@p3_a,@p3_a,1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5005);
SET @p3_ok=(SELECT COUNT(*)=@p3_failed+1 FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_assert_true(DATABASE(),'transfer same account one Failed',@p3_ok,'Expected procedure contract');
CALL bank_lab.sp_expect_error(DATABASE(),'transfer amount 0','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,0,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer amount -1','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,-1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5001);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer amount NULL','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,NULL,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5001);
SET @p3_failed=(SELECT COUNT(*) FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_expect_error(DATABASE(),'transfer missing from','CALL {db}.sp_transfer_funds(-1,@p3_b,1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5002);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer missing to','CALL {db}.sp_transfer_funds(@p3_a,-1,1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5002);
SET @p3_ok=(SELECT COUNT(*)=@p3_failed FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_assert_true(DATABASE(),'transfer missing references no Failed',@p3_ok,'Expected procedure contract');
CALL sp_open_account(@p3_c2,@p3_b2,@p3_type,1000,NULL,NULL,@p3_low,@p3_number);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer insufficient funds','CALL {db}.sp_transfer_funds(@p3_low,@p3_a,1,''Online'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5004);
SET @p3_failed=(SELECT COUNT(*) FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_expect_error(DATABASE(),'transfer wrong branch','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Branch'',@p3_t2,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5010);
SET @p3_ok=(SELECT COUNT(*)=@p3_failed+1 FROM Transactions WHERE status='Failed');
CALL bank_lab.sp_assert_true(DATABASE(),'transfer unauthorized exactly one Failed',@p3_ok,'D4/A8 failure recorded after rollback');
DROP TRIGGER IF EXISTS p3_failed_logger_probe;
DELIMITER $$
CREATE TRIGGER p3_failed_logger_probe BEFORE INSERT ON Transactions FOR EACH ROW FOLLOWS trg_transactions_bi_device_owner
BEGIN
 IF NEW.status='Failed' THEN SIGNAL SQLSTATE '45000' SET MYSQL_ERRNO=5018,MESSAGE_TEXT='synthetic failed logger rejection'; END IF;
END$$
DELIMITER ;
CALL bank_lab.sp_expect_error(DATABASE(),'Failed logger cannot mask original authorization error','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Branch'',@p3_t2,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5010);
DROP TRIGGER p3_failed_logger_probe;
CALL bank_lab.sp_expect_error(DATABASE(),'transfer manager direct disallowed','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Branch'',@p3_m1,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5010);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer Online employee disallowed','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Online'',@p3_t1,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5010);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer invalid channel','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Other'',NULL,NULL,NULL,0,@p3_group,@p3_debit,@p3_credit)',5018);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer invalid lab mode','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,4,@p3_group,@p3_debit,@p3_credit)',5018);
SET @p3_old=(SELECT balance FROM Accounts WHERE account_id=@p3_a);
SET @p3_other_old=(SELECT balance FROM Accounts WHERE account_id=@p3_b);
SET @p3_rows=(SELECT COUNT(*) FROM Transactions);
SET @p3_audits=(SELECT COUNT(*) FROM Audit_Log);
CALL bank_lab.sp_expect_error(DATABASE(),'transfer injected failure','CALL {db}.sp_transfer_funds(@p3_a,@p3_b,1,''Online'',NULL,NULL,NULL,1,@p3_group,@p3_debit,@p3_credit)',5016);
SET @p3_ok=(SELECT balance=@p3_old AND (SELECT balance FROM Accounts WHERE account_id=@p3_b)=@p3_other_old AND (SELECT COUNT(*) FROM Transactions)=@p3_rows AND (SELECT COUNT(*) FROM Audit_Log)=@p3_audits FROM Accounts WHERE account_id=@p3_a);
CALL bank_lab.sp_assert_true(DATABASE(),'transfer failure atomic balances and rows',@p3_ok,'Expected procedure contract');
